const orders = $input.all().map(item => item.json);

const normalize = (value) =>
  String(value ?? '').trim().toLowerCase();

const toNumber = (value) =>
  Number(String(value ?? 0).replace(/\s/g, '').replace(',', '.')) || 0;

const getValue = (order, fields) => {
  for (const field of fields) {
    if (order[field] !== undefined && order[field] !== '') {
      return order[field];
    }
  }
  return '';
};

// Date actuelle au Maroc au format AAAA-MM-JJ
const dateParts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Africa/Casablanca',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const year = dateParts.find(part => part.type === 'year').value;
const month = dateParts.find(part => part.type === 'month').value;
const day = dateParts.find(part => part.type === 'day').value;

const reportDate = `${year}-${month}-${day}`;

const preparedOrders = orders.map(order => ({
  po_id: getValue(order, ['po_id', 'purchase_order_id', 'order_id']),
  supplier_name: getValue(order, ['supplier_name', 'supplier']),
  amount_mad: toNumber(
    getValue(order, ['amount_mad', 'total_amount', 'amount'])
  ),
  supplier_risk: normalize(
    getValue(order, ['supplier_risk', 'risk_supplier'])
  ),
  urgency: normalize(
    getValue(order, ['urgency', 'priority'])
  ),
}));

// Détection des doublons
const idCounts = {};

for (const order of preparedOrders) {
  if (order.po_id) {
    idCounts[order.po_id] = (idCounts[order.po_id] || 0) + 1;
  }
}

const highValueOrders = preparedOrders.filter(
  order => order.amount_mad >= 100000
);

const riskySupplierOrders = preparedOrders.filter(
  order => ['high', 'blocked', 'élevé', 'eleve'].includes(order.supplier_risk)
);

const urgentOrders = preparedOrders.filter(
  order => ['urgent', 'high', 'critical', 'critique'].includes(order.urgency)
);

const duplicateOrders = preparedOrders.filter(
  order => order.po_id && idCounts[order.po_id] > 1
);

const ordersRequiringApproval = preparedOrders.filter(order => {
  const isDuplicate = order.po_id && idCounts[order.po_id] > 1;
  const isHighValue = order.amount_mad >= 100000;

  const isRiskySupplier = [
    'high',
    'blocked',
    'élevé',
    'eleve'
  ].includes(order.supplier_risk);

  const isSensitiveUrgentOrder =
    ['urgent', 'critical', 'critique'].includes(order.urgency) &&
    order.amount_mad >= 50000;

  return (
    isDuplicate ||
    isHighValue ||
    isRiskySupplier ||
    isSensitiveUrgentOrder
  );
});

const totalAmount = preparedOrders.reduce(
  (sum, order) => sum + order.amount_mad,
  0
);

const highestOrder = [...preparedOrders].sort(
  (a, b) => b.amount_mad - a.amount_mad
)[0] || {};

let riskLevel = 'Low';

if (
  riskySupplierOrders.length > 0 ||
  duplicateOrders.length > 0 ||
  highValueOrders.length > 0
) {
  riskLevel = 'High';
} else if (
  urgentOrders.length > 0 ||
  totalAmount >= 200000
) {
  riskLevel = 'Medium';
}

return [{
  json: {
    report_date: reportDate,
    total_purchase_orders: preparedOrders.length,
    total_amount_mad: totalAmount,
    high_value_orders: highValueOrders.length,
    risky_supplier_orders: riskySupplierOrders.length,
    urgent_orders: urgentOrders.length,
    duplicate_orders: duplicateOrders.length,
    approval_required_count: ordersRequiringApproval.length,
    highest_order_id: highestOrder.po_id || 'N/A',
    highest_order_supplier: highestOrder.supplier_name || 'N/A',
    highest_order_amount_mad: highestOrder.amount_mad || 0,
    risk_level: riskLevel,
    approval_required: ordersRequiringApproval.length > 0
  }
}];

