const kpi = $('Calculate Purchase Order Risk').first().json;
const aiAlert = $json.output || '';

const now = new Date();
const approvalId =
  'PO-APP-' +
  now.toISOString().replace(/\D/g, '').slice(0, 14);

const baseUrl =
  'https://YOUR-N8N-DOMAIN/webhook/purchase-order-approval-decision';

return [{
  json: {
    ...kpi,
    approval_id: approvalId,
    decision_status: 'Pending',
    requested_at: now.toISOString(),
    decided_at: '',
    decision_by: '',
    action_result: 'Awaiting human approval',
    ai_alert: aiAlert,

    approve_url:
      `${baseUrl}?approval_id=${approvalId}&decision=approved&decision_by=Procurement%20Manager`,

    reject_url:
      `${baseUrl}?approval_id=${approvalId}&decision=rejected&decision_by=Procurement%20Manager`
  }
}];

const kpi = $('Calculate Purchase Order Risk').first().json;
const summary = $json.output || 'No AI summary available.';

const escapeHtml = (value) =>
  String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

const formattedSummary = escapeHtml(summary)
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/\n/g, '<br>');

const formatNumber = (value) =>
  Number(value || 0).toLocaleString('en-US');

const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body {
      font-family: Arial, sans-serif;
      color: #1f2937;
      padding: 30px;
    }
    h1 { color: #163a5f; }
    h2 { color: #2563eb; }
    table {
      width: 100%;
      border-collapse: collapse;
      margin: 20px 0;
    }
    th, td {
      border: 1px solid #d1d5db;
      padding: 10px;
      text-align: left;
    }
    th {
      background: #163a5f;
      color: white;
    }
    .risk {
      font-size: 20px;
      font-weight: bold;
      color: ${kpi.risk_level === 'High' ? '#dc2626' : '#d97706'};
    }
  </style>
</head>
<body>

<h1>ERP Procurement Risk Report</h1>

<p><strong>Report date:</strong> ${kpi.report_date}</p>
<p class="risk">Global risk level: ${kpi.risk_level}</p>

<table>
  <tr><th>KPI</th><th>Result</th></tr>
  <tr><td>Total purchase orders</td><td>${kpi.total_purchase_orders}</td></tr>
  <tr><td>Total amount</td><td>${formatNumber(kpi.total_amount_mad)} MAD</td></tr>
  <tr><td>High-value orders</td><td>${kpi.high_value_orders}</td></tr>
  <tr><td>Risky supplier orders</td><td>${kpi.risky_supplier_orders}</td></tr>
  <tr><td>Urgent orders</td><td>${kpi.urgent_orders}</td></tr>
  <tr><td>Duplicate orders</td><td>${kpi.duplicate_orders}</td></tr>
  <tr><td>Orders requiring approval</td><td>${kpi.approval_required_count}</td></tr>
  <tr><td>Highest purchase order</td><td>${kpi.highest_order_id}</td></tr>
  <tr><td>Supplier</td><td>${kpi.highest_order_supplier}</td></tr>
  <tr><td>Highest amount</td><td>${formatNumber(kpi.highest_order_amount_mad)} MAD</td></tr>
</table>

<h2>AI Procurement Analysis</h2>
<p>${formattedSummary}</p>

<h2>Recommended action</h2>
<p>Review sensitive purchase orders before supplier confirmation and ERP processing.</p>

</body>
</html>
`;

return [{
  json: {
    ...kpi,
    ai_summary: summary,
    html
  }
}];

